export function min(p1: Rect, p2: Rect): number {
    return Math.min(p1.x, p2.x) - Math.max(p1.x, p2.x) + p1.width;
}

export function max(p1: Rect, p2: Rect): number {
    return Math.max(p1.x, p2.x) - Math.min(p1.x, p2.x) + p1.width;
}

// Assuming equality-based grouping.
export function minPoint(p: Rect, points: Array<[number, number]>): number {
    const minPoint = points[0];
    const minDistance = Math.min(p.x, p2.x) - Math.max(p1.x, p2.x);

    for (let i = 1; i < points.length; i++) {
        const p1X = points[i].x;
        const p1Y = points[i].y;
        const p2X = points[i].x;
        const p2Y = points[i].y;

        if (p1X < minPoint[0] || p2X < minPoint[0] || p1X > minPoint[1] || p2X > minPoint[1]) {
            continue;
        }

        const distance = Math.abs(p1X - p2X) + Math.abs(p1Y - p2Y);
        if (distance < minDistance) {
            minPoint = {x: minPoint[0], y: minPoint[1]};
        }
    }

    return minPoint[0];
}
